create or replace function public.convert_quotation_to_order(p_quotation_id uuid) returns public.orders language plpgsql security definer set search_path=public as $$ declare q public.quotations; v public.quotation_versions; m public.mockup_sets; o public.orders; qi public.quotation_items; oi public.order_items; qis public.quotation_item_services; begin if not public.has_staff_role(array['owner','superadmin','super_admin','sales_admin','admin']) then raise exception 'Not authorized to convert quotation'; end if; select * into q from public.quotations where id=p_quotation_id and archived_at is null for update; if not found then raise exception 'Quotation not found or archived'; end if; if q.status <> 'approved' then raise exception 'Quotation must be approved before conversion'; end if; if q.has_pending_pricing then raise exception 'Pending pricing must be resolved before conversion'; end if; if q.approved_version_id is null then raise exception 'Approved quotation version is required'; end if; select * into v from public.quotation_versions where id=q.approved_version_id and quotation_id=q.id; if not found or v.version_status <> 'approved' then raise exception 'Approved quotation version is invalid'; end if; select * into m from public.mockup_sets where quotation_id=q.id and archived_at is null and status='approved' order by updated_at desc limit 1; if not found then raise exception 'Approved mockup is required before conversion'; end if; if exists(select 1 from public.orders where quotation_id=q.id) then raise exception 'Quotation has already been converted'; end if; insert into public.orders(order_number,quotation_id,quotation_version_id,approved_mockup_set_id,customer_name,company_name,customer_phone,customer_email,billing_address,shipping_address,status,total_amount,customer_notes,admin_notes,currency,source_snapshot,converted_at,converted_by,created_by,updated_by) values(public.next_order_number(),q.id,v.id,m.id,q.customer_name,q.company_name,q.customer_phone,q.customer_email,q.billing_address,coalesce(q.shipping_address,''),'baru',coalesce(q.confirmed_total,q.estimated_total,0),coalesce(q.public_notes,''),coalesce(q.internal_notes,''),q.currency,jsonb_build_object('quotation',to_jsonb(q),'version',v.snapshot,'mockup_set',to_jsonb(m)),now(),auth.uid(),auth.uid(),auth.uid()) returning * into o; for qi in select * from public.quotation_items where quotation_id=q.id and archived_at is null order by sort_order,created_at loop insert into public.order_items(order_id,quotation_item_id,product_id,product_name,quantity,unit_price,subtotal,notes,color,size,product_type,variant_id,variant_size_id,sku,variant_name,pricing_status,config_snapshot,required_services,estimated_total) values(o.id,qi.id,qi.product_id,qi.product_name_snapshot,qi.quantity,coalesce(qi.unit_price,0),coalesce(qi.subtotal,0),coalesce(qi.customer_notes,''),coalesce(qi.color_name_snapshot,''),coalesce(qi.size_name_snapshot,''),'quotation_product',qi.product_variant_id,qi.product_variant_size_id,qi.sku_snapshot,qi.variant_name_snapshot,qi.pricing_status,to_jsonb(qi),coalesce((select jsonb_agg(to_jsonb(s)) from public.quotation_item_services s where s.quotation_item_id=qi.id and s.archived_at is null),'[]'::jsonb),qi.subtotal) returning * into oi; for qis in select * from public.quotation_item_services where quotation_item_id=qi.id and archived_at is null order by sort_order,created_at loop insert into public.order_item_services(order_item_id,quotation_item_service_id,service_name,quantity,position,pricing_status,unit_price,flat_price,subtotal,notes,snapshot) values(oi.id,qis.id,qis.service_name_snapshot,qis.quantity,qis.position,qis.pricing_status,qis.unit_price,qis.flat_price,qis.subtotal,qis.notes,to_jsonb(qis)); end loop; end loop; insert into public.order_status_history(order_id,from_status,to_status,note,changed_by) values(o.id,null,'baru','Pesanan dibuat dari penawaran '||q.quotation_number,auth.uid()); update public.quotations set status='converted_to_order',converted_at=now(),updated_by=auth.uid() where id=q.id; insert into public.quotation_status_history(quotation_id,from_status,to_status,note,changed_by) values(q.id,'approved','converted_to_order','Dikonversi menjadi pesanan '||o.order_number,auth.uid()); return o; end; $$; grant execute on function public.convert_quotation_to_order(uuid) to authenticated;;
